--
-- Table structure for table `lottery_results`
--

DROP TABLE IF EXISTS `lottery_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `lottery_results` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `game_code` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `issue_number` varchar(80) COLLATE utf8mb4_unicode_ci NOT NULL,
  `premium` varchar(120) COLLATE utf8mb4_unicode_ci NOT NULL,
  `number` varchar(120) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `color` varchar(80) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `big_small` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT '',
  `sum_value` int DEFAULT '0',
  `open_time` datetime DEFAULT NULL,
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uq_result` (`game_code`,`issue_number`),
  KEY `idx_result_game` (`game_code`)
) ENGINE=InnoDB AUTO_INCREMENT=410 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

